const EfficientAnimatedContent = require('../../../audits/byte-efficiency/efficient-animated-content');
const WebInspector = require('../../../lib/web-inspector');
const assert = require('assert');

async function testGifOptimization() {
  const networkRecords = [
    {
      _resourceType: WebInspector.resourceTypes.Image,
      _mimeType: 'image/gif',
      _resourceSize: 5046000, // 5MB GIF
      url: 'https://example.com/demo.gif',
    },
  ];
  const artifacts = {
    devtoolsLogs: {[EfficientAnimatedContent.DEFAULT_PASS]: []},
  };

  const {results} = await EfficientAnimatedContent.audit_(artifacts, networkRecords);
  assert.equal(results.length, 1);
  assert.equal(results[0].url, 'https://example.com/demo.gif');
  assert.equal(results[0].totalBytes, 5046000);
  assert.equal(Math.round(results[0].wastedBytes), 4776000);
}

testGifOptimization().then(() => console.log('Test passed')).catch(err => console.error('Test failed', err));
